N = 2048
def merge(left, right, marker):
    before = marker + 1
    mapping = {'before':before, **left, 'marker':marker, **right}
    members = {before, *left.values(), marker, *right.values()}
    return mapping['before'] + mapping['marker'] + len(members)
left = {'left':1}
right = {'right':2}
total = 0
for i in range(N):
    total += merge(left, right, i)
print(total)
